const zips = ["12345", "1234", "12a45"];
const usernames = ["Ada_99", "x1", "9lives", "grace"];
const phones = ["(555) 123-4567", "(555)123-4567", "555-123-4567"];

const label = (ok) => (ok ? "valid" : "invalid");

function isZip(text) {
  return /^\d{5}$/.test(text);
}

function isUsername(text) {
  return /^[a-z]\w{2,9}$/i.test(text);
}

function isPhone(text) {
  return /^\(\d{3}\)\s?\d{3}-\d{4}$/.test(text);
}

for (const zip of zips) {
  console.log(`${zip}: ${label(isZip(zip))}`);
}
for (const name of usernames) {
  console.log(`${name}: ${label(isUsername(name))}`);
}
for (const phone of phones) {
  console.log(`${phone}: ${label(isPhone(phone))}`);
}

