const codes = ["AB-1234", "ab-1234", "ABC-123", "XY-98765"];
const colors = ["#1a2B3c", "#FFF", "00ff00", "#00FF00"];
const prices = ["$4.99", "$12.50", "4.99", "$3.5"];

const label = (ok) => (ok ? "valid" : "invalid");

function isProductCode(text) {
  return /^[A-Z]{2}-\d{4}$/.test(text);
}

function isHexColor(text) {
  return /^#[0-9a-f]{6}$/i.test(text);
}

function isPrice(text) {
  return /^\$\d+\.\d{2}$/.test(text);
}

for (const code of codes) {
  console.log(`${code}: ${label(isProductCode(code))}`);
}
for (const color of colors) {
  console.log(`${color}: ${label(isHexColor(color))}`);
}
for (const price of prices) {
  console.log(`${price}: ${label(isPrice(price))}`);
}

steps.body:
`test` only answers yes or no. To pull text out, call `match` with a `g` regex. It returns an array of every matching string (no groups), or `null` when nothing matches, so default it with `?? []` before you join or loop:

```javascript
console.log("3 apples, 12 pears".match(/\d+/g) ?? []); // [ '3', '12' ]
```

The matches are strings, so convert them with `Number` before doing math.

Parentheses make a **capture group**. Without `g`, `match` returns only the first match, but with details: `m[0]` is the whole match, and `m[1]`, `m[2]` are the groups, counted by their opening parenthesis. It is also `null` when nothing matches, so check it with `if` before reading groups, or read one group with `?.[1]` as in the JSON lesson.

```javascript
const m = "port=8080".match(/(\w+)=(\d+)/);
console.log(`${m[1]} is ${m[2]}`); // port is 8080
```

To get every match with its groups, loop over `matchAll`. It needs the `g` flag and throws a TypeError without it. Named groups `(?<name>...)` read better than numbers, and you get them from `match.groups.name`:

```javascript harness
const text = "host=local port=8080 debug=true";
{{code}}
```

```javascript
for (const m of text.matchAll(/(?<key>\w+)=(?<value>\w+)/g)) {
  console.log(m.groups.key);
}
```

example.code:
const fruit = "3 apples, 12 pears and 7 figs";
const config = "host=local port=8080 debug=true";

const numbers = fruit.match(/\d+/g) ?? [];
const total = numbers.reduce((sum, n) => sum + Number(n), 0);
console.log(`Numbers: ${numbers.join(", ")}`);
console.log(`Total: ${total}`);
const none = "no digits here".match(/\d+/g) ?? [];
console.log(`Numbers in plain text: ${none.length}`);

const first = config.match(/(\w+)=(\w+)/);
if (first) {
  console.log(`First pair: ${first[0]}`);
  console.log(`Key: ${first[1]}, value: ${first[2]}`);
}

for (const match of config.matchAll(/(?<key>\w+)=(?<value>\w+)/g)) {
  console.log(`${match.groups.key} -> ${match.groups.value}`);
}

