practice.solution:
const post = "Learning #javascript and #regex today #100DaysOfCode";
const quiet = "Just a quiet day";
const log = "deploy 2024-03-15 ok, rollback 2024-04-02 failed, deploy 2024-11-30 ok";

const tags = post.match(/#\w+/g) ?? [];
console.log(`Tags: ${tags.join(", ")}`);
console.log(`Count: ${tags.length}`);
const noTags = quiet.match(/#\w+/g) ?? [];
console.log(`Tags in quiet post: ${noTags.length}`);

const first = log.match(/(\d{4})-(\d{2})-(\d{2})/);
if (first) {
  console.log(`First date: ${first[0]}`);
  console.log(`Year: ${first[1]}, month: ${first[2]}`);
}

for (const match of log.matchAll(/(?<year>\d{4})-(?<month>\d{2})-\d{2}/g)) {
  console.log(`${match.groups.year}/${match.groups.month}`);
}

