const messy = "too    many   spaces";
const order = "3 apples and 12 pears";
const trip = "from 2024-01-15 to 2024-02-01";
const list = "a, b;c ,d";

function collapseSpaces(text) {
  return text.replaceAll(/\s+/g, " ");
}

function doubleCounts(text) {
  return text.replace(/(\d+) (\w+)/g, (_, count, item) => `${Number(count) * 2} ${item}`);
}

function toDayFirst(text) {
  return text.replace(/(\d{4})-(\d{2})-(\d{2})/g, "$3/$2/$1");
}

function splitList(text) {
  return text.split(/\s*[,;]\s*/);
}

console.log(collapseSpaces(messy));
console.log(doubleCounts(order));
console.log(toDayFirst(trip));
const items = splitList(list);
console.log(`${items.length} items: ${items.join(" | ")}`);

