practice.solution:
const chat = "Nice work :) but the build broke :( fix it :)";
const name = "Lovelace, Ada";
const spaced = "one  two   three";

function replaceSmileys(text) {
  return text.replace(/:([()])/g, (_, mouth) => (mouth === ")" ? "😊" : "😞"));
}

function toFirstLast(fullName) {
  return fullName.replace(/(\w+), (\w+)/, "$2 $1");
}

function splitWords(text) {
  return text.split(/\s+/);
}

console.log(replaceSmileys(chat));
console.log(toFirstLast(name));
const words = splitWords(spaced);
console.log(`${words.length} words: ${words.join(" | ")}`);
